src=json.load(open(f'{H}/tr/b001/source_es.json'))
out={}
for vid,s in src.items():
    p,n,q,a,ex=T[vid]
    rec=p+ex
    assert len(p)==3 and len(n)==len(s['nouns']) and len(rec)==len(s['recall']), vid
    out[vid]={"phrases":p,"nouns":n,"question":q,"answer":a,"captions":{},"recall":rec}
assert set(T)==set(src)
json.dump(out,open(f'{H}/tr/b001/es/ua.json','w'),ensure_ascii=False,indent=1)
